css:
.aero-button {
  position: relative;
  cursor: pointer;
  border-radius: 4px;
  border: 1px solid #3d80b1;
  background: #d3ecfb;
  overflow: hidden;
  isolation: isolate;
  transition: 0.05s all;
}

.aero-button::before {
  content: "";
  position: absolute;
  inset: 0;
  top: 50%;
  background: linear-gradient(
    90deg,
    #8bd2f6,
    #a7dbf7 30%,
    #a7dbf7 50%,
    #7bcaf4
  );
  z-index: -1;
  transition: inherit;
}

.aero-button::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  box-shadow: inset 0px 0px 0px 1px #dcf1fc;
  z-index: 1;
  transition: inherit;
}

.inner {
  position: relative;
  display: flex;
  flex-direction: row;
  padding: 4px;
  transition: inherit;
}

.inner svg {
  height: 2.4em;
  margin: auto;
  transition: inherit;
}

.aero-button:hover {
  background: #f3feff;
}

.aero-button:hover::before {
  background: linear-gradient(
    90deg,
    #7ae4ff,
    #b7fbfe 30%,
    #b7fbfe 50%,
    #7ae4ff
  );
}

.aero-button:active {
  border: 1px solid #1d415b;
  background: #a9d8f2;
}

.aero-button:active::before {
  background: linear-gradient(
    90deg,
    #6abce8,
    #98d1f0 30%,
    #98d1f0 50%,
    #6abce8
  );
  translate: 1px 1px;
}

.aero-button:active::after {
  box-shadow:
    inset 2px 2px 4px -2px #0007,
    inset -2px 2px 4px -2px #0007;
}

.aero-button:active .inner {
  translate: 1px 1px;
}
